#include <cstdio>
#include <cmath>

struct V { float x, y, z; };
struct Hero { bool exists, dead; V pos; };
static float g_ax = 0; static int g_pushes = 0;
static void Jostle(const V& spirit, long ownPlayer, long mainPlayer, const Hero* heroes)
