            if (d->type == type && d->happening && d->target == target) { if (out) *out = d->handle; return d; }
        }
    for (int i = 0; i < nk; ++i) {
        const Deed* d = &known[i];
        if (d->happening && d->target == target) { if (out) *out = d->handle; return d; }
    }
    return 0;
}

